const mockComments = [
    {
        id: 1,
        displayName: "AlexB",
        category: "Feedback",
        commentText: "Really enjoyed today’s stream! I’d love to see more tactical FPS content. Maybe a stream focused on specific strategies?",
        createdAt: "2 hours ago"
    },
    {
        id: 2,
        displayName: "JordanK",
        category: "Ideas",
        commentText: "It would be awesome to have a community game night once a month where followers can join in.",
        createdAt: "5 hours ago"
    },
    {
        id: 3,
        displayName: "SamW",
        category: "Questions",
        commentText: "What setup are you currently using for your streams? The video quality has looked really good lately.",
        createdAt: "1 day ago"
    },
    {
        id: 4,
        displayName: "ChrisT",
        category: "Feedback",
        commentText: "The new layout looks clean. I really like how easy it is to move through the site.",
        createdAt: "1 day ago"
    },
    {
        id: 5,
        displayName: "MorganL",
        category: "General",
        commentText: "Just wanted to say the community here has been really fun lately. Keep it up.",
        createdAt: "2 days ago"
    }
];

export async function getComments() {

    return new Promise(function(resolve) {

        setTimeout(function() {
            resolve(mockComments);
        }, 300);

    });

}

export async function createComment(newComment) {

    return new Promise(function(resolve) {

        setTimeout(function() {

            const comment = {
                id: Date.now(),
                ...newComment,
                createdAt: "Just now"
            };

            mockComments.unshift(comment);

            resolve(comment);

        }, 300);

    });

}
